export const NIC_CODE_MAP: Record<string, NicSubclass> = Object.fromEntries(
  NIC_CODES.map(c => [c.code, c])
);

export function getNicByDivision(divisionCode: string): NicSubclass[] {
  return NIC_CODES.filter(c => c.divisionCode === divisionCode);
}

export function getNicBySection(section: string): NicSubclass[] {
  return NIC_CODES.filter(c => c.section === section);
}

export function searchNicCodes(query: string): NicSubclass[] {
  const q = query.toLowerCase();
  return NIC_CODES.filter(c =>
    c.description.toLowerCase().includes(q) ||
    c.className.toLowerCase().includes(q) ||
    c.groupName.toLowerCase().includes(q) ||
    c.divisionName.toLowerCase().includes(q)
  );
}